sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {
    var tasktype = current.task_status.toString();
    var caseSysID = current.sys_id;
    var query = "";

    switch (tasktype) {
        case 'CALLBACK_NOTREQUIRED':
        case 'REVIEW_COMPLETED.APPROVE':
            new x_hsb11_mss_unst_0.MSS_Unstructured_Instruction_Utils().deactivateMT599Instructions(caseSysID); //MSSCUSTODY-7169
            query = 'active=true^task_type=Instruction^restrictedccy=false^instruction_case=' + caseSysID;
            new x_hsb11_mss_unst_0.MSS_Unstructured_Instruction_Utils().generateInstructionJSON(caseSysID, query, current.u_message_id, current.u_objectid, current.owning_business, current.instruction_type.toString());
            break;

        case 'CALLBACK_REQUIRED':
            new x_hsb11_mss_unst_0.MSS_Unstructured_Instruction_Utils().deactivateMT599Instructions(caseSysID); //MSSCUSTODY-7169
            var rowIDs = processCallback();
            if (rowIDs.length > 0) {
                query = 'active=true^task_type=Instruction^restrictedccy=false^instruction_case=' + caseSysID + '^swbrowidIN' + rowIDs.toString();
                new x_hsb11_mss_unst_0.MSS_Unstructured_Instruction_Utils().generateInstructionJSON(caseSysID, query, current.u_message_id, current.u_objectid, current.owning_business, current.instruction_type.toString());
            }
            break;
        case 'CALLBACK_VERIFICATION_COMPLETED.SUCCESS':
            var rowIDs = processCallback();
            if (rowIDs.length > 0) {
                query = 'active=true^task_type=Instruction^restrictedccy=false^instruction_case=' + caseSysID + '^swbrowidIN' + rowIDs.toString();
                new x_hsb11_mss_unst_0.MSS_Unstructured_Instruction_Utils().generateInstructionJSON(caseSysID, query, current.u_message_id, current.u_objectid, current.owning_business, current.instruction_type.toString());
            }
            break;
        default:
            break;
    }

    // To retrieves relevant subrow IDs.
    function processCallback() {
        var subrowIDs = [];
        var groutbound = new GlideRecord("x_hsb11_hsbcmss_sw_hsbc_swb_outbound_table");
        groutbound.addEncodedQuery('process_status=UPDATE_CALLBACK_DATA^reference_id=' + caseSysID);
        groutbound.query();

        if (groutbound.next()) {
            try {
                var requestBody = groutbound.getValue('request_body');
                var parsedBody = JSON.parse(requestBody);

                if (parsedBody.Data) {
                    for (var i = 0; i < parsedBody.Data.length; i++) {
                        var row = parsedBody.Data[i];

                        if (tasktype == 'CALLBACK_REQUIRED' && (row.OverThresholdFlag == false || row.CallbackFlag == false))
                            subrowIDs.push(row.SwbRowId);
                        else if (tasktype == 'CALLBACK_VERIFICATION_COMPLETED.SUCCESS' && row.OverThresholdFlag == true && row.CallbackFlag == true)
                            subrowIDs.push(row.SwbRowId);
                    }
                }
            } catch (e) {
                gs.error('Error in Business Rule: MSS Unstructured Json creation for ITM ' + e.message);
            }
        }
        return subrowIDs;
    }
})(current, previous);
